create sequence public.kombax_brand_audit_v223_id_seq;
create table public.kombax_brand_audit_v223(id bigint default nextval('kombax_brand_audit_v223_id_seq'::regclass), brand_profile_id uuid, actor_id uuid, action text, object_type text, object_id uuid, before_state jsonb, after_state jsonb, created_at timestamp with time zone default now());
create table public.kombax_brand_campaigns_v223(id uuid default gen_random_uuid(), brand_profile_id uuid, title text, campaign_type text, visibility text default 'private'::text, status text default 'draft'::text, description text, territory text, disciplines text[] default '{}'::text[], audience_types text[] default '{}'::text[], compensation_type text, compensation_summary text, conditions_summary text, starts_at timestamp with time zone, ends_at timestamp with time zone, created_by uuid, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now());
create table public.kombax_brand_profiles_v223(brand_profile_id uuid, sector text, territories text[] default '{}'::text[], disciplines text[] default '{}'::text[], collaboration_open boolean default false, inbound_proposals boolean default true, public_business_summary text, updated_by uuid, updated_at timestamp with time zone default now());
create table public.kombax_brand_proposals_v223(id uuid default gen_random_uuid(), brand_profile_id uuid, campaign_id uuid, target_type text, target_direct_profile_id uuid, target_club_id uuid, target_event_id uuid, source text default 'brand_invite'::text, status text default 'pending'::text, message text, terms_summary text, response_note text, created_by uuid, responded_by uuid, created_at timestamp with time zone default now(), updated_at timestamp with time zone default now(), responded_at timestamp with time zone);
create table public.kombax_brand_team_roles_v223(brand_profile_id uuid, perfil_id uuid, business_role text, updated_by uuid, updated_at timestamp with time zone default now());
